<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>畅行旅行 - 首页</title>
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body{margin:0;font-family:Arial,Helvetica,sans-serif;background:#f5f5f5;}
        .header{background:#fff;padding:20px 0;border-bottom:1px solid #e0e0e0;}
        .header .logo{font-size:28px;font-weight:bold;color:#ff5a5f;text-align:center;}
        .nav{display:flex;justify-content:center;margin-top:10px;}
        .nav a{margin:0 15px;color:#333;text-decoration:none;}
        .nav a:hover{color:#ff5a5f;}
        .container{max-width:1440px;margin:auto;padding:20px;}
        .search-form{background:#fff;padding:20px;border-radius:5px;box-shadow:0 2px 4px rgba(0,0,0,.1);}
        .search-form label{display:block;margin-bottom:5px;font-weight:bold;}
        .search-form input{width:100%;padding:8px;border:1px solid #ccc;border-radius:4px;margin-bottom:15px;}
        .search-form button{background:#ff5a5f;color:#fff;border:none;padding:10px 20px;border-radius:4px;cursor:pointer;}
        .search-form button:hover{background:#e04e4e;}
        footer{background:#fff;text-align:center;padding:15px;margin-top:30px;border-top:1px solid #e0e0e0;font-size:14px;color:#777;}
        @media (max-width:600px){
            .nav{flex-direction:column;}
            .nav a{margin:5px 0;}
        }
    </style>
</head>
<body>
    <header class="header">
        <div class="logo">畅行旅行</div>
        <nav class="nav">
            <a href="index.html">首页</a>
            <a href="search.html">搜索结果</a>
            <a href="booking.html">预订中心</a>
        </nav>
    </header>
    <main class="container">
        <section class="search-form">
            <h2>搜索您的旅行目的地</h2>
            <form action="search.html" method="get">
                <label for="destination">目的地</label>
                <input type="text" id="destination" name="destination" placeholder="如：杭州、桂林" required>
                <label for="checkin">入住日期</label>
                <input type="date" id="checkin" name="checkin" required>
                <label for="checkout">退房日期</label>
                <input type="date" id="checkout" name="checkout" required>
                <button type="submit">搜索酒店</button>
            </form>
        </section>
    </main>
    <footer>
        © 2026 畅行旅行 - 旅游预订服务
    </footer>
</body>
</html>

